WITH filtered AS (SELECT id, order_id, quantity, unit_price, ROUND(unit_price / quantity, 2) line_total FROM order_items WHERE product_id IS NOT NULL), scored AS (SELECT *, COUNT(line_total) OVER (PARTITION BY order_id ORDER BY unit_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_count_line_total, SUM(line_total) OVER (PARTITION BY order_id ORDER BY unit_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_sum_line_total, AVG(line_total) OVER (PARTITION BY order_id ORDER BY unit_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_avg_line_total, LAG(unit_price, 1, 0) OVER (PARTITION BY order_id ORDER BY line_total, id) prev_unit_price FROM filtered WHERE unit_price BETWEEN 200 AND 390), base AS (SELECT id, quantity, unit_price, line_total, running_count_line_total, running_sum_line_total, GREATEST(running_count_line_total, quantity) greatest_running_count_line_total_quantity FROM scored WHERE unit_price < 110), metrics AS (SELECT *, COUNT(line_total) OVER w_ordered running_count_line_total_2, MAX(line_total) OVER w_ordered running_max_line_total, SUM(line_total) OVER w_ordered running_sum_line_total_2, MIN(line_total) OVER w_ordered running_min_line_total FROM base WINDOW w_ordered AS (ORDER BY running_count_line_total, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), metrics_order_items AS (SELECT *, CUME_DIST() OVER (ORDER BY unit_price DESC) unit_price_cume_dist, LAG(running_count_line_total, 1, 0) OVER w_recent prev_running_count_line_total FROM metrics WINDOW w_recent AS (ORDER BY unit_price, id)) SELECT id, unit_price, line_total, running_count_line_total, running_sum_line_total, greatest_running_count_line_total_quantity, running_count_line_total_2, running_sum_line_total_2, running_min_line_total FROM metrics_order_items ORDER BY running_sum_line_total_2 DESC;
